import subprocess
argv = ["pacman", "-S", "r23x-tuple-module-foreign"]
def make(argv):
    def run():
        subprocess.run(argv)
    return (run, argv)
def arm(argv, pair):
    callback, _ = pair
    def fire():
        callback()
    return fire
job = arm(["pacman", "-S", "r23x-tuple-forwarder-foreign"], make(["pacman", "-Q", "r23x-tuple-captured"]))
